{
  "name": "@amykit/plugin-notify-hermes",
  "version": "0.7.0",
  "description": "Announcements over Hermes, which already owns the messaging credentials.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/notify-hermes"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.7.0",
    "@amykit/plugin-notify-fanout": "^0.7.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { CommandRunner, ConfigSchema } from "@amykit/core";
import { Channel } from "@amykit/plugin-notify-fanout";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  target: {
    type: "string",
    required: true,
    description:
      "a Hermes delivery target, such as `slack:my-channel` or a bare platform name for its home channel",
  },
} satisfies ConfigSchema;

export interface HermesListing {
  platforms?: Record<string, { id?: string; name?: string }[]>;
}

/**
 * Whether Hermes actually has the target configured.
 *
 * Checked against `--list --json` rather than the human-readable listing,
 * because that listing ends with a usage line naming a platform as an
 * example. Matching on the text would pass for a platform that is only
 * mentioned in the help.
 *
 * Target format is `platform`, `platform:chat_id`,
 * `platform:chat_id:thread_id` or `platform:#channel-name`.
 */
export function hermesTargetIsKnown(listing: HermesListing, target: string): boolean {
  const separator = target.indexOf(":");
  const platform = separator === -1 ? target : target.slice(0, separator);
  const targets = listing.platforms?.[platform];

  if (!targets) return false;
  // A bare platform name sends to that platform's home channel.
  if (separator === -1) return true;

  const wanted = target.slice(separator + 1).replace(/^#/, "");

  // A thread target is `chat_id:thread_id`, which Hermes already reports
  // joined in the id, so an exact match covers it.
  return targets.some(
    (candidate) => candidate.id === wanted || candidate.name === wanted,
  );
}

/**
 * Hands the announcement to Hermes, which already owns the messaging
 * credentials, so this does not need any of its own.
 */
export function hermesChannel(runner: CommandRunner, target: string): Channel {
  return {
    name: `hermes:${target}`,
    async deliver(announcement) {
      const result = await runner.run(
        "hermes",
        ["send", "--to", target, "--quiet", "--subject", `amy ${announcement.workId}`],
        { stdin: announcement.text, timeoutMs: 60_000 },
      );

      if (!result.ok) {
        throw new Error(result.stderr || result.stdout || "hermes send failed");
      }
    },
  };
}

export { configSchema, hermesChannel, hermesTargetIsKnown } from "./hermesChannel.js";
export type { HermesListing } from "./hermesChannel.js";
export { plugin } from "./plugin.js";

import { definePlugin } from "@amykit/core";
import { CHANNEL_COLLECTION } from "@amykit/plugin-notify-fanout";
import { configSchema, hermesChannel, hermesTargetIsKnown } from "./hermesChannel.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-notify-hermes",
  configSchema,
  register(registry, ctx) {
    const target = ctx.config.target;

    registry.contribute(CHANNEL_COLLECTION, "hermes", hermesChannel(ctx.runner, target));

    // The port's own knowledge, asked rather than re-derived: whether a
    // delivery target is reachable is something only this plugin knows, and
    // the host asking would mean the host importing one notifier's reader —
    // the dependency this plugin exists to keep out of the command.
    registry.port("notify", {
      async isReachable(asked: string) {
        if (asked !== target) return false;

        const result = await ctx.runner.run(
          "hermes",
          ["send", "--list", "--json"],
          { timeoutMs: 60_000 },
        );
        if (!result.ok) {
          throw new Error(result.stderr.split("\n")[0] || "hermes send --list failed");
        }

        return hermesTargetIsKnown(JSON.parse(result.stdout), asked);
      },
    });
  },
});
